SELECT * FROM product
WHERE product_id = #{productId}
  AND is_deleted = 'N'

SELECT *
FROM product
WHERE is_deleted = 'N'
  AND (
      category_id = #{categoryId}
      OR category_id IN (
          SELECT category_id
          FROM category
          WHERE parent_id = #{categoryId}
      )
  )
ORDER BY product_id DESC

SELECT name
FROM category
WHERE category_id = #{categoryId}

SELECT spec_key AS specKey, spec_value AS specValue
FROM product_spec
WHERE product_id = #{productId}

mapper.update:
UPDATE product
SET is_deleted = 'Y'
WHERE product_id = #{productId}
